import _ from 'lodash';
import { strict as assert } from 'node:assert';

import { Field } from 'meteor/pwix:field';
import SimpleSchema from 'meteor/aldeed:simple-schema';
import { Tracker } from 'meteor/tracker';

import { States } from './index.js';

States._defaultFieldsDef = function(){
    let columns = [
        // --
        // _id: the document identifier generated by Mongo at insert time.
        //  it is used as 'state' parameter (an identifier of the flow)
        // -- 
        //  the GrantType definition
        {
            name: 'grantType',
            type: Object,
            optional: true,
            blackbox: true
        },
        // the params provided by the caller, depend of the chosen grant type
        {
            name: 'params',
            type: Object,
            optional: true,
            blackbox: true
        },
        // the PKCE challenge generated at insert time, even if at the moment we don't know if we will use it (though this is very probable)
        // the code_challenge will be sent to the AuthorizationServer from the client browser as an element of first communication
        // the code_verifier will be sent later from the server when exchanging the authorization code for an access token
        // as a consequence code_verifier nevers goes to the client
        {
            name: 'pkce',
            type: Object,
            optional: true,
            blackbox: true
        }
    ];
    columns = columns.concat( Timestampable.fieldDef());
    return columns;
};

Tracker.autorun(() => {
    let columns = States._defaultFieldsDef();
    let fieldset = new Field.Set( columns );
    States.fieldSet.set( fieldset );
});
